function icon(string $name, string $class = '', array $attrs = []): string
{
    $inner = LUCIDE_ICONS[$name] ?? '';
    $extra = '';
    foreach ($attrs as $k => $v) { $extra .= ' ' . $k . '="' . htmlspecialchars((string)$v, ENT_QUOTES) . '"'; }
    return '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-' . $name . ($class !== '' ? ' ' . $class : '') . '"' . $extra . '>' . $inner . '</svg>';
}

/** Lightweight icon that references a shared <symbol> (see icon_sprite()). */
function icon_use(string $name, string $class = ''): string
{
    return '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-' . $name . ($class !== '' ? ' ' . $class : '') . '"><use href="#i-' . $name . '"></use></svg>';
}

/** Hidden sprite with the given icons as <symbol>s. */
function icon_sprite(array $names): string
{
    $out = '<svg xmlns="http://www.w3.org/2000/svg" style="display:none" aria-hidden="true">';
    foreach ($names as $n) {
        $out .= '<symbol id="i-' . $n . '" viewBox="0 0 24 24">' . (LUCIDE_ICONS[$n] ?? '') . '</symbol>';
    }
    return $out . '</svg>';
}
